"""Render the measured pilot and its actual saved evidence packs."""

import json
import csv
from html import escape as html_escape
from collections import Counter
from pathlib import Path

from run import atomic

ROOT = Path(__file__).resolve().parent


def main():
    manifest = json.loads((ROOT / "manifest.json").read_text())
    readings = []
    for item in manifest["jobs"]:
        jid = item["job_id"]
        readings.append({**item, "job": json.loads((ROOT / "inputs" / f"{jid}.json").read_text()),
                         "reading": json.loads((ROOT / "compiled" / f"{jid}.json").read_text())["record"]})
    claims = [c for r in readings for c in r["reading"]["claims"]]
    review = json.loads((ROOT / "semantic-review.json").read_text())
    data = {"readings": readings, "review": review,
            "packs": json.loads((ROOT / "evidence-packs.json").read_text()),
            "checks": json.loads((ROOT / "checks.json").read_text()),
            "summary": {"jobs": len(readings), "sources": sum(len(r["job"]["sources"]) for r in readings),
                        "claims": len(claims), "mentions": sum(len(r["reading"]["mentions"]) for r in readings),
                        "families": dict(Counter(c["family"] for c in claims)),
                        "genres": dict(Counter(r["reading"]["episode"]["genre"] for r in readings)),
                        "alternatives": sum(len(r["reading"]["reading_groups"]) for r in readings),
                        "needs_context": sum(r["reading"]["episode"]["coverage"] == "needs_context" for r in readings)},
            "source": {"lake_snapshot": 1, "method": manifest["selection"], "limits": manifest["limits"]}}
    atomic(ROOT / "report-data.json", data)
    css = (ROOT / "report.css").read_text()
    template = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Passage reading pilot</title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Inter+Tight:wght@500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>@@CSS@@
.wrap{max-width:1050px}body{background-color:var(--paper)}h1{max-width:850px}h2{font-weight:600}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--rule-strong);background:var(--paper-card);border-radius:var(--radius)}.stats>div{padding:20px;border-right:1px solid var(--rule)}.stats>div:last-child{border:0}.stats strong{display:block;font:500 30px var(--font-mono);color:var(--green)}.stats span{display:block;font-size:14px;margin-top:7px}.stage-list{padding-left:24px}.stage-list li{padding:8px 0}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:end;margin:20px 0}.controls label{display:flex;flex-direction:column;gap:8px;min-width:180px}select,input{font:inherit;color:var(--ink);background:var(--paper-card);border:1px solid var(--rule-strong);padding:10px;border-radius:var(--radius)}input{width:100%}.figure-wrap{overflow-x:auto;border:1px solid var(--rule);background:var(--paper-card);border-radius:var(--radius);margin:20px 0}.figure-wrap svg{display:block;min-width:690px;width:100%;max-width:960px}svg text{fill:var(--ink);font:14px var(--font-body)}svg .relation{fill:var(--green);font:13px var(--font-mono)}svg .box{fill:var(--paper-tint);stroke:var(--rule-strong)}svg .link{fill:none;stroke:var(--green);stroke-width:2}svg .bar{fill:var(--green)}svg .axis{stroke:var(--rule-strong)}.evidence{border-top:1px solid var(--rule);padding:16px 0}.evidence blockquote{font:21px/1.8 serif;text-align:right;margin:12px 0;padding:12px;background:var(--paper-tint)}.plain-meta{color:var(--ink-mid);font-size:14px}.notice{background:var(--paper-tint);border:1px solid var(--rule);border-radius:var(--radius);padding:20px}.notice p:first-child{margin-top:0}.kvrow{display:grid;grid-template-columns:160px 1fr;gap:20px;border-top:1px solid var(--rule);padding:12px 0}.review-row{padding:12px 0;border-top:1px solid var(--rule)}.badge{display:inline-block;border:1px solid var(--rule-strong);border-radius:999px;padding:3px 9px;font:12px var(--font-mono);color:var(--ink-mid)}.warning{color:var(--warn)}.case-list details{margin:0;border-bottom:1px solid var(--rule);padding:14px 0}.case-list summary{cursor:pointer;display:flex;justify-content:space-between;gap:15px;align-items:center}.case-content{padding:15px 4px}.case-content h3{font-size:17px}.case-content pre{white-space:pre-wrap;font:13px var(--font-mono)}.wide{overflow-x:auto}table{min-width:550px;width:100%;border-collapse:collapse}th,td{padding:10px 12px;border-bottom:1px solid var(--rule);text-align:left;font-size:14px}th{background:var(--paper-tint);border-bottom:1px solid var(--rule-strong)}.claim-text{overflow-wrap:anywhere}.muted{color:var(--ink-mid)}section{scroll-margin-top:20px}.source-ref{font:12px var(--font-mono)}@media(max-width:650px){.stats{grid-template-columns:1fr 1fr}.stats>div:nth-child(2){border-right:0}.stats>div{border-bottom:1px solid var(--rule)}.kvrow{grid-template-columns:1fr;gap:4px}.case-list summary{align-items:start;flex-direction:column}}@media print{.controls,#theme,nav{display:none}.case-list details{break-inside:avoid}body{background:var(--paper)}}
</style></head><body><main class="wrap">
<header><div class="topline"><span class="eyebrow">Sage graph study · Passage pilot</span><button class="btn" id="theme">Light / dark</button></div>
<h1>Whole passages give us richer links. Some readings still need fixing.</h1>
<p>We can now save people, actions and alternative versions together with the words that support them. The next job is to decide which readings and identities deserve a place in the historical graph.</p>
<nav aria-label="On this page"><a href="#one">One real evidence pack</a><a href="#saved">What we saved</a><a href="#review">What the checks found</a><a href="#all">All passages</a><a href="#next">What comes next</a></nav></header>
<section id="one"><span class="eyebrow">01 / Follow a link back to the text</span><h2>One pack keeps the source, the choices and the reason.</h2>
<p>Choose a case, then a reading. These are saved results from the pilot. A diagram shows what that reading says; it does not certify that the event happened.</p>
<div class="controls"><label>Passage<select id="pack"></select></label><label>Reading<select id="candidate"></select></label></div>
<div id="pack-content"></div></section>
<section id="saved"><span class="eyebrow">02 / What the readers saved</span><h2>Thirty difficult cases and twelve randomly chosen passages.</h2>
<div class="stats" id="stats"></div><p id="coverage-text"></p>
<p>The random group has six passages from each Talmud. It was chosen before reading, without filtering for known names. Each includes nearby text. This is a small trial of the method, not an accuracy estimate for the whole text.</p>
<div class="figure-wrap" id="family-chart"></div><div class="wide"><table><thead><tr><th>Kind</th><th>One actual saved claim and its words</th></tr></thead><tbody id="family-examples"></tbody></table></div>
<details class="acc"><summary>What is saved with every claim</summary><div class="case-content"><ol class="stage-list"><li><strong>Exact words.</strong> Passage, edition, text hash and matching character span.</li><li><strong>Local people and things.</strong> Named people, relatives, groups, statements and events.</li><li><strong>Relationship and direction.</strong> Who acts, whom they address and what they discuss.</li><li><strong>Reading conditions.</strong> Speaker, alternative version, negation, question or assertion.</li><li><strong>Open questions.</strong> Missing context and reading confidence. Historical identity and historical confidence remain unset.</li></ol></div></details>
</section>
<section id="review"><span class="eyebrow">03 / Good files can still contain wrong readings</span><h2>The independent reading is the more important check.</h2>
<div id="review-summary" class="notice"></div><div id="findings"></div>
<details class="acc"><summary>How the checks work</summary><div class="case-content"><p id="structural"></p><p>Each extraction was checked by a reader who did not write it. The difficult cases use a checklist prepared before extraction. The random cases were checked directly against the supplied text. Reviewers also looked for errors beyond the checklist.</p><p>This is provisional review, without human adjudication. A checklist can be wrong or incomplete. Agreement with it is not proof of complete extraction.</p><p>The first readings stay saved. Review findings do not silently rewrite them. An evidence pack can accept a narrow textual claim while leaving other claims from that episode open.</p></div></details>
</section>
<section id="all"><span class="eyebrow">04 / Inspect the actual readings</span><h2>Every passage has its own sources and review.</h2><label for="search">Find a passage, person or relationship</label><input id="search" type="search" placeholder="For example: Menachot, wife, asks"><p id="visible-count" class="plain-meta"></p><div id="cases" class="case-list"></div></section>
<section id="next"><span class="eyebrow">05 / From this pilot to the larger graph</span><h2>Fix what this trial exposed before rereading everything.</h2>
<ol class="stage-list"><li><strong>Make speech content more precise.</strong> Save what was asked, imagined or predicted as its own structured statement. That prevents a character’s words from becoming a historical event.</li><li><strong>Resolve missing context and review findings.</strong> Fetch the surrounding discussion when needed. Save each corrected reading as a new revision.</li><li><strong>Run a larger blind check.</strong> Freeze the revised instructions, read a broader random sample, and measure missed claims as well as unsupported claims.</li><li><strong>Build identity evidence packs.</strong> Compare local people across passages. Keep supported matches, competing candidates and reasons. Add biographies as separately sourced evidence.</li><li><strong>Build the historical graph and dates.</strong> Use reviewed decisions. Let every edge open its evidence pack. Keep genre, conflicting versions and unresolved identities visible.</li></ol>
<p>The reusable records and four evidence packs are built. A production extraction service, global person matching and a dated historical graph still lie ahead.</p>
<details class="acc"><summary>Files, sources and reuse</summary><div class="case-content"><p>The input collection is sage_network lake snapshot 1. The report, source snapshots, raw readings, compiled spans, reviews, pack decisions and code are saved together. Source edition and licence appear with each passage below.</p><p>Exact data: <a href="report-data.json">report-data.json</a> · <a href="evidence-packs.json">evidence-packs.json</a> · <a href="README.md">run instructions</a>. The page itself contains its data and works without those files.</p></div></details></section>
</main><script id="data" type="application/json">@@DATA@@</script><script>
const D=JSON.parse(document.getElementById('data').textContent), $=id=>document.getElementById(id);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const readings=Object.fromEntries(D.readings.map(r=>[r.job_id,r])), reviews=Object.fromEntries(D.review.cases.map(r=>[r.job_id,r]));
const labels={family:'Family',transmission:'Transmission',teaching:'Teaching',speech:'Speech',views:'Views',scenes:'Scenes',time:'Time'};
const words=p=>p.replaceAll('_',' ');
const entity=(r,id)=>r.entities.find(e=>e.id===id)?.label??id;
const sourceLink=ref=>{let i=ref.lastIndexOf(' ');return 'https://www.sefaria.org/'+ref.slice(0,i).replaceAll(' ','_')+'.'+ref.slice(i+1).replaceAll(':','.');};
function claimLine(r,c){return escape(entity(r,c.subject))+' <strong>'+escape(words(c.predicate))+'</strong> '+escape(entity(r,c.object));}
function claimHTML(r,c,j){const branch=c.branches.length?c.branches.join(' / '):'Shared reading';return `<div class="evidence"><div class="claim-text">${claimLine(r,c)}</div><p class="plain-meta">${escape(c.id)} · ${escape(branch)} · ${escape(c.polarity)} · ${escape(c.modality)} · ${escape(c.discourse_status)} · reading confidence: ${escape(c.reading_confidence)}</p>${c.evidence.map(a=>{let s=j.sources.find(s=>s.source_id===a.source_id);return `<blockquote lang="he" dir="rtl">${escape(a.quote)}</blockquote><span class="source-ref"><a href="${escape(sourceLink(s.ref))}" target="_blank" rel="noopener">${escape(s.ref)}</a> · ${escape(s.edition)}</span>`}).join('')}${c.roles.length?'<p class="plain-meta">'+c.roles.map(x=>escape(words(x.role))+': '+escape(entity(r,x.entity))).join(' · ')+'</p>':''}${c.notes.map(n=>'<p>'+escape(n)+'</p>').join('')}</div>`;}
function wrapText(text,x,y,width=26){const words=String(text).split(' '),lines=[];let current='';for(const w of words){if((current+' '+w).trim().length>width&&current){lines.push(current);current=w;}else current=(current+' '+w).trim();}if(current)lines.push(current);return `<text x="${x}" y="${y-(lines.length-1)*9}" text-anchor="middle">${lines.map((l,i)=>`<tspan x="${x}" dy="${i?19:0}">${escape(l)}</tspan>`).join('')}</text>`;}
function graph(pack,candidate){let r=readings[pack.job_id].reading,selected=candidate.supporting_claims.map(ref=>r.claims.find(c=>c.id===ref.split('/')[1]));if(pack.id==='reversed-speakers')selected=selected.filter(c=>c.predicate==='answers');let height=selected.length*125+32;let paths='',boxes='';selected.forEach((c,i)=>{let y=i*125+55,object=c.object,label=words(c.predicate);let to=c.roles.find(x=>x.role==='addressee');if(pack.id==='reversed-speakers'&&to){object=to.entity;label='explains to';}if(c.polarity==='negative')label=c.predicate==='rules_like'?'does not rule like':'not: '+label;if(pack.id==='woman-or-tractate'){let target=c.roles.find(x=>['partner','referent','object','with'].includes(x.role));if(target)object=target.entity;label='story describes';}let symmetric=['spouse_of','sibling_of','travels_with'].includes(c.predicate);paths+=`<path class="link" d="M275 ${y+10} H605" ${symmetric?'':'marker-end="url(#arrow)"'}/>`;boxes+=`<rect class="box" x="15" y="${y-22}" width="260" height="66" rx="6"/><rect class="box" x="605" y="${y-22}" width="260" height="66" rx="6"/>${wrapText(entity(r,c.subject),145,y+14)}${wrapText(entity(r,object),735,y+14)}<rect x="294" y="${y-30}" width="292" height="25" fill="var(--paper-card)"/><text class="relation" x="440" y="${y-12}" text-anchor="middle">${escape(label)}</text>`;});return `<div class="figure-wrap"><svg class="chart" viewBox="0 0 880 ${height}" role="img" aria-label="${escape(candidate.description)}"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="none" stroke="var(--green)"/></marker></defs>${paths}${boxes}</svg></div>`;}
$('pack').innerHTML=D.packs.packs.map((p,i)=>`<option value="${i}">${escape(readings[p.job_id].ref)} · ${escape(p.question)}</option>`).join('');
function choosePack(){let p=D.packs.packs[+$('pack').value];$('candidate').innerHTML=p.candidates.map((c,i)=>`<option value="${i}">${escape(c.description)}</option>`).join('');showPack();}
function showPack(){let p=D.packs.packs[+$('pack').value],c=p.candidates[+$('candidate').value],d=D.packs.decisions.find(d=>d.pack_id===p.id),reading=readings[p.job_id];let ids=c.supporting_claims.map(x=>x.split('/')[1]);$('pack-content').innerHTML=`<h3>${escape(p.question)}</h3>${graph(p,c)}<div class="kvrow"><strong>Saved decision</strong><div>${escape(d.conclusion)}</div></div><div class="kvrow"><strong>Why</strong><div>${escape(d.reason)}</div></div><div class="kvrow"><strong>Probability</strong><div>Not estimated. Saving two readings does not make them equally likely.</div></div><div class="kvrow"><strong>Historical status</strong><div>Not yet approved for the historical graph.</div></div><p>${p.limits.map(escape).join(' ')}</p><details class="acc"><summary>Read the exact evidence and saved claims</summary><div class="case-content">${reading.reading.claims.filter(c=>ids.includes(c.id)).map(c=>claimHTML(reading.reading,c,reading.job)).join('')}<p>${escape(p.search_coverage)}</p><p class="plain-meta">${escape(p.shared_dependencies.join(' '))}</p></div></details>`;}
$('pack').addEventListener('change',choosePack);$('candidate').addEventListener('change',showPack);choosePack();
let s=D.summary;$('stats').innerHTML=[[s.jobs,'episodes read'],[s.claims,'candidate claims'],[s.alternatives,'alternative groups'],[D.packs.packs.length,'evidence packs']].map(([n,l])=>`<div><strong>${n.toLocaleString()}</strong><span>${l}</span></div>`).join('');
$('coverage-text').textContent=`The jobs contain ${s.sources} supplied source segments and ${s.mentions} saved mention spans. ${s.needs_context} readings ask for more context. These counts describe the saved output, not how much of the whole Talmud is finished.`;
let fs=Object.keys(labels),max=Math.max(...Object.values(s.families)),bars=fs.map((f,i)=>{let y=40+i*45,n=s.families[f]??0;return `<text x="20" y="${y+5}">${labels[f]}</text><rect class="bar" x="180" y="${y-12}" width="${n/max*560}" height="22"/><text x="${195+n/max*560}" y="${y+5}" style="font-family:var(--font-mono)">${n}</text>`}).join('');$('family-chart').innerHTML=`<svg class="chart" viewBox="0 0 880 350" role="img" aria-label="Candidate claim counts by relationship family">${bars}</svg>`;
$('family-examples').innerHTML=fs.map(f=>{let chosen={family:'challenge-20',transmission:'challenge-04',teaching:'challenge-11',speech:'challenge-05',views:'challenge-02',scenes:'challenge-13',time:'challenge-01'};let rr=readings[chosen[f]]??D.readings.find(r=>r.reading.claims.some(c=>c.family===f));if(!rr)return `<tr><td>${labels[f]}</td><td>No saved claim in this pilot.</td></tr>`;let c=rr.reading.claims.find(c=>c.family===f);return `<tr><td>${labels[f]}</td><td>${claimLine(rr.reading,c)}<br><span class="plain-meta">${escape(rr.ref)} · ${escape(c.modality)} · ${escape(c.polarity)}${c.branches.length?' · alternative reading':''}</span><div lang="he" dir="rtl" style="font:18px/1.6 serif;margin-top:10px">${escape(c.evidence[0].quote)}</div></td></tr>`}).join('');
let major=D.review.jobs_with_missed_checks_or_major_findings,flagged=D.review.jobs_with_findings_or_uncertainty,cc=D.review.check_counts;
$('review-summary').innerHTML=`<p><strong>${D.review.job_count} readings received an independent review.</strong> ${major.length} have a missed checklist item or a major finding. ${flagged.length} have some finding or uncertainty to keep visible.</p><p>Checklist results: ${cc.pass??0} pass, ${cc.miss??0} miss, ${cc.uncertain??0} uncertain, ${cc.not_applicable??0} not applicable. These are individual checks, not percentages of passages correctly understood.</p>`;
let findings=D.review.cases.flatMap(r=>r.additional_findings.filter(f=>f.severity==='major').map(f=>({ref:readings[r.job_id].ref,...f}))).slice(0,6);$('findings').innerHTML=findings.map(f=>`<div class="review-row"><strong>${escape(f.ref)}</strong> <span class="badge">${escape(words(f.type))}</span><p>${escape(f.reason)}</p></div>`).join('');
$('structural').textContent=`All ${D.checks.real_jobs} readings pass the saved-record checks. ${D.checks.checks.length-1} deliberate changes to real records were rejected, including broken quotes, missing people and branch leakage. Those tests check structure, not meaning.`;
function showCases(){let q=$('search').value.trim().toLowerCase();let visible=D.readings.filter(r=>JSON.stringify(r).toLowerCase().includes(q));$('visible-count').textContent=`${visible.length} of ${D.readings.length} episodes shown`; $('cases').innerHTML=visible.map(rr=>{let r=rr.reading,v=reviews[rr.job_id];let issues=v.checks.filter(c=>['miss','uncertain'].includes(c.status));return `<details><summary><strong>${escape(rr.ref)}</strong><span class="plain-meta">${r.claims.length} claims · ${escape(r.episode.genre)} · ${escape(rr.group)}</span></summary><div class="case-content"><p>${escape(v.summary)}</p><p><strong>Passage type:</strong> ${escape(r.episode.genre_reason)}</p>${r.episode.needed_context.length?'<p class="warning"><strong>More context needed:</strong> '+r.episode.needed_context.map(escape).join(' ')+'</p>':''}${issues.map(c=>`<div class="notice"><strong>${escape(c.status)}</strong> ${escape(c.reason)}</div>`).join('')}${v.additional_findings.map(f=>`<p><strong>${escape(f.severity)} ${escape(f.type)}:</strong> ${escape(f.reason)}</p>`).join('')}<h3>Claims saved by the first reader</h3>${r.claims.map(c=>claimHTML(r,c,rr.job)).join('')}<h3>Full supplied source text</h3>${rr.job.sources.map(s=>`<div class="evidence"><a href="${escape(sourceLink(s.ref))}" target="_blank" rel="noopener">${escape(s.ref)}</a><blockquote lang="he" dir="rtl">${escape(s.text)}</blockquote><p class="plain-meta">${escape(s.edition)} · licence: ${escape(s.provenance.license??s.provenance.hebrew_license??'see source metadata')}</p></div>`).join('')}</div></details>`}).join('');}showCases();$('search').addEventListener('input',showCases);
$('theme').addEventListener('click',()=>{let current=document.documentElement.dataset.theme??(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');document.documentElement.dataset.theme=current==='dark'?'light':'dark';});
let wasOpen=[];window.addEventListener('beforeprint',()=>{wasOpen=[...document.querySelectorAll('details')].map(d=>[d,d.open]);wasOpen.forEach(([d])=>d.open=true)});window.addEventListener('afterprint',()=>wasOpen.forEach(([d,open])=>d.open=open));
</script></body></html>'''
    html = template.replace("@@CSS@@", css).replace("@@DATA@@", json.dumps(data, ensure_ascii=False).replace("<", "\\u003c"))
    (ROOT / "report.html").write_text(html)
    families = ["family", "transmission", "teaching", "speech", "views", "scenes", "time"]
    with (ROOT / "family-counts.csv").open("w", newline="") as stream:
        writer = csv.writer(stream)
        writer.writerow(["family", "candidate_claims", "episodes_read"])
        writer.writerows((f, data["summary"]["families"].get(f, 0), len(readings)) for f in families)
    top = max(data["summary"]["families"].values())
    bars = []
    for i, family in enumerate(families):
        y = 65 + i * 45
        n = data["summary"]["families"].get(family, 0)
        width = n / top * 560
        bars.append(f'<text x="20" y="{y+5}">{html_escape(family.title())}</text><rect x="180" y="{y-12}" width="{width}" height="22" fill="var(--green)"/><text x="{195+width}" y="{y+5}">{n}</text>')
    svg_style = css + '\ntext{fill:var(--ink);font:14px var(--font-mono)}'
    (ROOT / "claims-by-family.svg").write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 880 395" data-theme="light"><style>' + svg_style + '</style><rect width="880" height="395" fill="var(--paper-card)"/><text x="20" y="25">Candidate claims from 42 episodes; historical links unapproved</text>' + ''.join(bars) + '</svg>')
    print(json.dumps(data["summary"], indent=2))


if __name__ == "__main__":
    main()
